import {AudioEngine} from './engine.js';
const $=x=>document.querySelector(x),sleep=ms=>new Promise(r=>setTimeout(r,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async bytes=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');
function measure(buffer){return Array.from({length:buffer.numberOfChannels},(_,channel)=>{const all=buffer.getChannelData(channel),start=Math.min(Math.floor(.1*buffer.sampleRate),Math.floor(all.length/4)),data=all.subarray(start),cross=[];let power=0,peak=0,finite=true;for(let i=0;i<data.length;i++){const x=data[i];finite&&=Number.isFinite(x);power+=x*x;peak=Math.max(peak,Math.abs(x));if(i&&data[i-1]<0&&x>=0)cross.push(i-1-data[i-1]/(x-data[i-1]));}return{frames:all.length,measuredStartFrame:start,measuredFrames:data.length,finite,rms:Math.sqrt(power/data.length),peak,frequencyHz:cross.length>1?(cross.length-1)*buffer.sampleRate/(cross.at(-1)-cross[0]):null};});}
$('#run').onclick=async()=>{
 $('#run').disabled=true;$('#captures').textContent='';const engine=new AudioEngine(),checks=[],captures=[],errors=[],report={startedAt:new Date().toISOString(),sourceHashes:{},checks,captures,errors,scope:'Actual AudioEngine and browser MediaRecorder/decode. Synthetic source tones; settled metrics skip first100ms of decoded codec stream; original encoded files remain complete. No physical/native/latency/first-frame/Seratoquality acceptance.'};
 let cueDestination;
 const publish=()=>{$('#results').textContent=JSON.stringify(report,null,2);$('#status').textContent=`${checks.filter(x=>x.passed).length}/${checks.length}passed`;};
 try{
  engine.init();engine.audioMonitor.mutePhysical(true);await engine.resume();
  for(const file of ['engine.js','audio-monitor.js','audio-monitor-engine-harness.js'])report.sourceHashes[file]=await hash(await(await fetch(file)).arrayBuffer());
  engine.onError=error=>errors.push({name:error.name,message:error.message});
  cueDestination=engine.ctx.createMediaStreamDestination();engine.audioMonitor.headphones.connect(cueDestination);
  const track={id:'monitor-engine-fixture',duration:48,bpm:120},deck={index:0,track,playing:false,position:0,anchorPosition:0,anchorTime:0,rate:1,keylock:false,keyShift:0,reverse:false,loop:false,loopIn:0,loopOut:4,stems:[true,true,true,true],stemFX:[false,false,false,false]};
  function tone(left,right){const b=engine.ctx.createBuffer(2,engine.ctx.sampleRate*48,engine.ctx.sampleRate);for(let c=0;c<2;c++){const a=b.getChannelData(c);for(let i=0;i<a.length;i++)a[i]=.12*Math.sin(2*Math.PI*(c?right:left)*i/b.sampleRate);}return b;}
  engine.buffers.set(track.id,tone(440,660));engine.setMonitorSettings({mix:0,volume:.1,masterCue:false,splitCue:false,mono:false});await engine.start(deck);
  async function capture(label){await sleep(160);const entries=[['master',engine.destination.stream],['cue',cueDestination.stream]].map(([bus,stream])=>{const recorder=new MediaRecorder(stream),chunks=[];let resolve,reject;const done=new Promise((a,b)=>{resolve=a;reject=b;});recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onerror=e=>reject(Error(e.error?.message||'Recorder failed'));recorder.onstop=()=>resolve(new Blob(chunks,{type:recorder.mimeType}));recorder.start();return{bus,recorder,done};});await sleep(600);for(const entry of entries)entry.recorder.stop();const results={};for(const entry of entries){const blob=await entry.done,bytes=await blob.arrayBuffer(),buffer=await engine.ctx.decodeAudioData(bytes.slice(0)),name=`monitor-engine-${label}-${entry.bus}.webm`,link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=name;link.textContent=name;$('#captures').append(link,document.createElement('br'));const evidence={name,bus:entry.bus,bytes:bytes.byteLength,sha256:await hash(bytes),mime:blob.type,sampleRate:buffer.sampleRate,channels:measure(buffer)};captures.push(evidence);results[entry.bus]=evidence.channels;}return results;}
  async function check(name,label,setup,verify){let evidence;try{await setup();evidence=await capture(label);verify(evidence);checks.push({name,passed:true,evidence});}catch(error){checks.push({name,passed:false,evidence,error:error.message,stack:error.stack});}publish();}
  const silent=data=>assert(data.every(x=>x.finite&&x.peak<.00002),'Expected quiet captured bus: '+JSON.stringify(data));
  const audible=(data,left=440,right=660,minimumRMS=.02)=>{assert(data.length===2,'Expected stereo capture');for(const [c,hz]of [left,right].entries())assert(data[c].finite&&data[c].rms>minimumRMS&&Math.abs(data[c].frequencyHz-hz)<hz*.02,'Expected captured tone: '+JSON.stringify({data,hz,c}));};
  await check('Selected cue survives zero channel level and opposite crossfader','prefader',async()=>{engine.mix(0,'level',0);engine.setCross(1);engine.setPFL(0,true);},e=>{silent(e.master);audible(e.cue);});
  await check('Turning PFL off silences its independent headphone bus','pfl-off',async()=>engine.setPFL(0,false),e=>{silent(e.master);silent(e.cue);});
  await check('Raising master deck does not silently select it for cue','master-only',async()=>{engine.mix(0,'level',1);engine.setCross(0);},e=>{audible(e.master);silent(e.cue);});
  await check('Master Cue overrides cue mixture with actual postmaster audio','master-cue',async()=>engine.setMonitorSettings({masterCue:true,splitCue:true}),e=>{audible(e.master);audible(e.cue);for(let c=0;c<2;c++)assert(Math.abs(e.master[c].rms-e.cue[c].rms)<.01,'Master Cue gain differs');});
  await check('Unit-FX route rebuild preserves pre-fader cue and master buses','fx-layout',async()=>{engine.setMonitorSettings({masterCue:false,splitCue:false});engine.setPFL(0,true);engine.configureFX([[{name:'LPF',on:false,depth:0,beat:'1/2',params:{}}]],['Deck 1']);},e=>{audible(e.master);audible(e.cue);});
  await check('Changing Channel FX retains actual cue audio connection','channel-fx',async()=>{await engine.setChannelFX('Dub Echo');engine.nodes[0].channelValue=.2;await engine.applyChannelFX(0);},e=>{audible(e.master);audible(e.cue);});
  await check('Actual selected vocal stem reaches cue without original or other stems','vocal-stem',async()=>{await engine.setChannelFX('Filter');engine.nodes[0].channelValue=0;await engine.applyChannelFX(0);await engine.attachStems(track,[tone(173,211),tone(251,277),tone(337,359),tone(419,443)],[deck]);deck.stems=[true,false,false,false];engine.updateStems(deck);},e=>{audible(e.master,173,211);audible(e.cue,173,211);});
  await check('Selected Stem Slip vocal cue survives the opposite crossfader','stem-slip-prefader',async()=>{await engine.setStemSlip(deck,'vocal');engine.setCross(1);engine.setPFL(0,true);},e=>{silent(e.master);audible(e.cue,173,211);});
  const priorVocal=checks.at(-1).evidence;
  await check('Stem Slip cue and main both follow changed channel EQ','stem-slip-eq',async()=>{engine.setCross(0);engine.mix(0,'low',-12);},e=>{audible(e.master,173,211,.005);audible(e.cue,173,211,.005);for(let c=0;c<2;c++){assert(e.cue[c].rms<priorVocal.cue[c].rms*.7,'Cue ignored EQ');assert(Math.abs(e.master[c].rms/e.cue[c].rms-.55)<.03,'Cue and master EQ paths differ');}});
  await check('Stem Slip cue follows active low-pass filter before the crossfader','stem-slip-filter',async()=>{engine.mix(0,'low',0);engine.mix(0,'filter',-1);},e=>{for(let c=0;c<2;c++){assert(e.cue[c].finite&&e.cue[c].rms>.0001&&e.cue[c].rms<priorVocal.cue[c].rms*.3,'Cue filter attenuation missing');assert(Math.abs(e.master[c].rms/e.cue[c].rms-.55)<.03,'Filter paths differ');}});
  await check('Stem Slip cue retains independent Channel FX at opposite crossfader','stem-slip-channel-fx',async()=>{engine.setCross(1);await sleep(160);engine.mix(0,'filter',0);await engine.setChannelFX('Dub Echo');engine.nodes[0].channelValue=.2;await engine.applyChannelFX(0);engine.setCross(1);},e=>{silent(e.master);audible(e.cue,173,211);});
  await check('Instrumental Slip leaves complementary vocal master and cue audible','stem-slip-complement',async()=>{await engine.setChannelFX('Filter');engine.nodes[0].channelValue=0;await engine.applyChannelFX(0);await engine.setStemSlip(deck,'instrumental');},e=>{audible(e.master,173,211);audible(e.cue,173,211);});
  await check('Selected instrumental Stem Slip cue survives the opposite crossfader','stem-slip-instrumental',async()=>{deck.stems=[false,true,false,false];engine.updateStems(deck);},e=>{silent(e.master);audible(e.cue,251,277);});
  await check('Leaving Stem Slip restores one ordinary cue path with no doubled gain','stem-slip-exit',async()=>engine.setStemSlip(deck,'off'),e=>{silent(e.master);audible(e.cue,251,277);for(const channel of e.cue)assert(channel.rms<.1,'Cue doubled after Stem Slip exit');});
  await check('Global silence clears voices and reconnects safe channel graph without cue leaks','silence',async()=>engine.silence(),e=>{silent(e.master);silent(e.cue);});
 }catch(error){report.fatalError={message:error.message,stack:error.stack};}
 finally{try{engine.silence();await engine.ctx?.close();}catch(error){errors.push({phase:'cleanup',message:error.message});}report.passed=checks.filter(x=>x.passed).length;report.failed=checks.length-report.passed;report.completed=checks.length===15&&report.failed===0&&!report.fatalError&&!errors.length;publish();const link=$('#download');link.href=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));link.download='audio-monitor-engine-browser-results.json';link.hidden=false;$('#run').disabled=false;}
};
